429	
430	\begin{lemma}[Combined line measurements]
431		\label{lem:qld-xz-lines}
432		\lean{MIPStarRE.QPBT.CombinedLinesWitness}
433		\lean{MIPStarRE.QPBT.exists_combinedLinesWitness}
