534	\begin{definition}[The combining map]
535		\label{def:combine-map}
536		\lean{MIPStarRE.QPBT.combinePoly, MIPStarRE.QPBT.combinePoly_eval}
537		\lean{MIPStarRE.QPBT.combinePoly_mem_polyFunc}
538		\lean{MIPStarRE.QPBT.combineLinePoly}
