541		\notready
542		\uses{def:polyfunc, def:line, def:ideg-deg-polynomials}
543		For $f, g \in \mathrm{ideg}_{d,m}(\F_q)$, the polynomial
544		$\mathrm{combine}_{f,g} \in \mathrm{ideg}_{d,2m+2}(\F_q)$ is defined by
545		\[
546			\mathrm{combine}_{f,g}(x, z, \alpha, \beta)
547			= \alpha f(x) + \beta g(z)\,,
548			\qquad x \in \F_q^m,\ z \in \F_q^m,\ \alpha \in \F_q,\
549			\beta \in \F_q\,.
550		\]
551		The combining map is also defined for polynomials restricted to lines.
552		Let $\ell$ be a line in $\F_q^{2m+2}$ with intercept
553		$u = (u_X, u_Z, u_\alpha, u_\beta)$ and slope
554		$v = (v_X, v_Z, v_\alpha, v_\beta)$, and let $\ell_X$ and $\ell_Z$ be
555		lines in $\F_q^m$ such that for every point
556		$(x, z, \alpha, \beta) \in \ell$ it holds that $x \in \ell_X$ and
557		$z \in \ell_Z$. Then for any two polynomials
558		$f \in \deg_{md}(\ell_X)$ and $g \in \deg_{md}(\ell_Z)$, the polynomial
559		$\mathrm{combine}_{f,g} \in \deg_{md+1}(\ell)$ is defined by
560		\begin{equation}
561			\label{eq:combine-lines}
562			\mathrm{combine}_{f,g}(u + t \cdot v)
563			= (u_\alpha + t \cdot v_\alpha)\, f(u_X + t \cdot v_X)
564			+ (u_\beta + t \cdot v_\beta)\, g(u_Z + t \cdot v_Z)\,,
565			\qquad t \in \F_q\,.
566		\end{equation}
567		The degree bound holds because $f$ and $g$, restricted to lines, are
568		polynomials of degree at most $md$ in the line parameter, and each is
569		multiplied by an affine factor of degree at most one.
570	\end{definition}
